pub(super) fn p1b_alignment__trace_link(
    mut requirement_id: Value,
    mut risk_id: Value,
    mut risk_node: Value,
    mut test_node: Value,
    mut execution_node: Value,
    mut coverage_nodes: Value,
    mut changed_nodes: Value,
) -> Result<Value> {
    let mut execution_data: Value;
    let mut test_data: Value;
    test_data = (if (test_node.clone().is_object()) {
        get(&test_node, &json!("data"), json!({}))
    } else {
        json!({})
    });
    execution_data = (if (execution_node.clone().is_object()) {
        get(&execution_node, &json!("data"), json!({}))
    } else {
        json!({})
    });
    return Ok(Value::Object(
        [
            ("requirement_id".into(), requirement_id.clone()),
            ("risk_id".into(), risk_id.clone()),
            (
                "risk_node_id".into(),
                json!(values::text(&get(&risk_node, &json!("id"), json!("")))),
            ),
            (
                "risk_severity".into(),
                get(
                    &get(&risk_node, &json!("data"), json!({})),
                    &json!("severity"),
                    json!(""),
                ),
            ),
            ("changed_code_refs".into(), {
                let mut collected_values = Vec::new();
                for current in sequence(&changed_nodes)? {
                    let mut node = current;
                    collected_values.push(Value::Object(
                        [
                            (
                                "node_id".into(),
                                json!(values::text(&get(&node, &json!("id"), json!("")))),
                            ),
                            (
                                "path".into(),
                                get(
                                    &get(&node, &json!("data"), json!({})),
                                    &json!("path"),
                                    json!(""),
                                ),
                            ),
                            (
                                "start_line".into(),
                                get(
                                    &get(&node, &json!("data"), json!({})),
                                    &json!("start_line"),
                                    Value::Null,
                                ),
                            ),
                            (
                                "end_line".into(),
                                get(
                                    &get(&node, &json!("data"), json!({})),
                                    &json!("end_line"),
                                    Value::Null,
                                ),
                            ),
                        ]
                        .into_iter()
                        .collect(),
                    ));
                }
                Value::Array(collected_values)
            }),
            (
                "test_node_id".into(),
                (if (test_node.clone().is_object()) {
                    json!(values::text(&get(&test_node, &json!("id"), json!(""))))
                } else {
                    json!("")
                }),
            ),
            (
                "canonical_test_id".into(),
                json!(values::text(&get(
                    &test_data,
                    &json!("canonical_test_id"),
                    json!("")
                ))),
            ),
            (
                "test_status".into(),
                json!(values::text(&get(&test_data, &json!("status"), json!("")))),
            ),
            (
                "execution_node_id".into(),
                (if (execution_node.clone().is_object()) {
                    json!(values::text(&get(&execution_node, &json!("id"), json!(""))))
                } else {
                    json!("")
                }),
            ),
            (
                "execution_status".into(),
                json!(values::text(&get(
                    &execution_data,
                    &json!("status"),
                    json!("")
                ))),
            ),
            ("coverage_refs".into(), {
                let mut collected_values = Vec::new();
                for current in sequence(&coverage_nodes)? {
                    let mut node = current;
                    collected_values.push(Value::Object(
                        [
                            (
                                "node_id".into(),
                                json!(values::text(&get(&node, &json!("id"), json!("")))),
                            ),
                            (
                                "file".into(),
                                get(
                                    &get(&node, &json!("data"), json!({})),
                                    &json!("file"),
                                    json!(""),
                                ),
                            ),
                            (
                                "contexts".into(),
                                get(
                                    &get(&node, &json!("data"), json!({})),
                                    &json!("contexts"),
                                    Value::Array(vec![]),
                                ),
                            ),
                        ]
                        .into_iter()
                        .collect(),
                    ));
                }
                Value::Array(collected_values)
            }),
            (
                "evidence_state".into(),
                (if (truth(&test_node)) && (truth(&execution_node)) {
                    json!("covered")
                } else {
                    json!("missing_execution")
                }),
            ),
            (
                "source_refs".into(),
                Value::Array(vec![json!("qeg-bundle.json")]),
            ),
        ]
        .into_iter()
        .collect(),
    ));
}
